  ui_story_32160401_65_dialog_content = "Hahaha...!",
  ui_story_32160401_66_dialog_content = "Para de rir!",
  ui_story_32160401_67_dialog_content = "Eu sei o que você quis dizer:",
  ui_story_32160401_68_dialog_content = "Artesãos geniais podem obter inspiração de qualquer coisa.",
  ui_story_32160401_69_dialog_content = "Concordo que é verdade, mas não acho que seja a chave.",
  ui_story_32160401_70_dialog_content = "Não, na verdade, é exatamente o oposto.",
  ui_story_32160401_71_dialog_content = "Em relação aos aparelhos...",
  ui_story_32160401_72_dialog_content = "Apenas aqueles que conseguem se inspirar em algo além de aparelhos eletrônicos podem se tornar gênios artesãos.",
  ui_story_32160401_73_dialog_content = "A verdadeira sabedoria está em todas as coisas e na natureza. Nós apenas aplicamos isso aos dispositivos.",
  ui_story_32160401_74_dialog_content = "Acho que entendi, mas não tenho certeza...",
  ui_story_32160401_75_dialog_content = "Falando em natureza, por que tantos gadgets têm a forma de animais?",
  ui_story_32160401_76_dialog_content = "Boa pergunta.",
  ui_story_32160401_77_dialog_content = "Qianyun, minha escola de artesanato, acredita:",
  ui_story_32160401_78_dialog_content = "Não importa quão complexo seja um dispositivo, ele não se compara à obra da natureza.",
  ui_story_32160401_79_dialog_content = "As formas e poderes de todas as coisas e como elas alcançam a Lúmina são resultados de milênios de sobrevivência.",
  ui_story_32160401_80_dialog_content = "É o que mais combina com eles no momento.",
  ui_story_32160401_81_dialog_content = "Então, Qianyun acredita que imitar os animais é imitar a natureza. Esse é o caminho.",
  ui_story_32160401_82_dialog_content = "Claro, você não está imitando a aparência deles, mas sim como eles funcionam.",
  ui_story_32160401_83_dialog_content = "Pegue, por exemplo, construir algo que possa escalar uma árvore.",
  ui_story_32160401_84_dialog_content = "A chave não é fazer com que pareça um macaco, mas sim como os membros do macaco funcionam.",
  ui_story_32160401_85_dialog_content = "Observe como eles se movem, imite como eles agem e, finalmente, obtenha o resultado que deseja.",
  ui_story_32160401_86_dialog_content = "Entendi... Parece a teoria emergente do simulacro de certos laboratórios Illumina.",
  ui_story_32160401_87_dialog_content = "Perto, embora os artesãos de Longzhou estejam trabalhando nisso há milhares de anos.",
  ui_story_32160401_88_dialog_content = "Acho que essa é uma das razões pelas quais os dois lados estão seguindo em direções diferentes.",
  ui_story_32160401_89_dialog_content = "Sim, estou muito mais claro agora.",
  ui_story_32160401_90_dialog_content = "E quanto a dispositivos que não se parecem com animais? Como...",
  ui_story_32160401_91_dialog_content = "Tal como o Guarda-sol Peculiar?",
  ui_story_32160401_92_dialog_content = "Sim!",
  ui_story_32160401_93_dialog_content = "Bem, isso é porque os princípios por trás disso envolviam mais do que apenas a escola de design Qianyun...",
  ui_story_32160401_94_dialog_content = "Mas o jeito Dikun também.",
  ui_story_32160401_95_dialog_content = "Dikun é completamente diferente de Qianyun.",
  ui_story_32160401_96_dialog_content = "Eles acreditam que todas as coisas que crescem naturalmente são inerentemente falhas.",
  ui_story_32160401_97_dialog_content = "Criaturas que nadam no mar morrem quando estão fora da água. Criaturas voadoras são frágeis. Criaturas terrestres estão presas à terra.",
  ui_story_32160401_98_dialog_content = "Apenas criações artificiais podem ser livres de defeitos. Somente nós podemos tornar a perfeição possível.",
  ui_story_32160401_99_dialog_content = "E como você não precisa mexer na perfeição, deve ser inanimado.",
  ui_story_32160401_100_dialog_content = "É por isso que eles não seguem a escola antiga de fazer suas criações se parecerem com animais.",
  ui_story_32160401_101_dialog_content = "Então, eles tendem a criar principalmente armadilhas e dispositivos passivos, adicionando eventualmente pólvora à mistura.",
  ui_story_32160401_102_dialog_content = "Você não parece ser contra o Dikun?",
  ui_story_32160401_103_dialog_content = "Por que eu deveria? Essa é a sabedoria de todos os artesãos antes de eu nascer também.",
  ui_story_32160401_104_dialog_content = "Isso me ajudou muito, tanto quanto a panela quente.",
  ui_story_32160401_105_dialog_content = "Se você quer saber, sou contra o status quo atual entre as duas escolas.",
  ui_story_32160401_106_dialog_content = "Eles discutem e brigam para sempre, se afastando cada vez mais da arte.",
  ui_story_32160401_107_dialog_content = "Mas o fato é: eles nem estão lutando para fazer invenções melhores.",
  ui_story_32160401_108_dialog_content = "Em vez disso, eles querem que as pessoas reconheçam sua superioridade, para que seus respectivos alunos pareçam mais dignos perante o rei.",
  ui_story_32160401_109_dialog_content = "Discussões como essa são o que estagnam as técnicas de construção de dispositivos no Reino Ye...",
  ui_story_32160401_110_dialog_content = "É por isso que fiz o guarda-sol, apenas para provar o quão sem sentido é a disputa deles.",
  ui_story_32160401_111_dialog_content = "É por isso que é o seu favorito e você o carrega todos os dias?",
  ui_story_32160401_112_dialog_content = "Isso mesmo. Tem profissionais de ambas as escolas.",
  ui_story_32160401_113_dialog_content = "Imita funcionalidades e é versátil. Também é portátil, como certos gadgets.",
  ui_story_32160401_114_dialog_content = "Este guarda-sol contém libélulas de cobre e pássaros mecânicos, além de dardos e contas.",
  ui_story_32160401_115_dialog_content = "Ativa e passiva, ambas as escolas estão em uma só. Você pode chamar isso de minha obra-prima.",
  ui_story_32160401_116_dialog_content = "Interessante... Isso me dá vontade de criar meu próprio gadget.",
  ui_story_32160401_117_dialog_content = "Bem, embora eu reconheça seu talento e inteligência...",
  ui_story_32160401_118_dialog_content = "Não é tão fácil assim começar do zero sem nenhuma experiência.",
  ui_story_32160401_119_option_content = "Ensine-me, Xuan Ji! Não... Mestre Xuan Ji!",
  ui_story_32160401_120_dialog_content = "Pare de me bajular! Bem, posso te mostrar algo simples. Considere isso como eu retribuindo o favor.",
  ui_story_32160401_121_dialog_content = "Então você não vai achar que eu sou bom apenas para panelas quentes.",
  ui_story_32160401_122_option_content = "Ok. Qual é um começo simples que posso fazer?",
  ui_story_32160401_123_dialog_content = "Deixe-me pensar... Ah, entendi.",
  ui_story_32160401_124_dialog_content = "O medalhão de coração que fiz antes. Vamos começar com ele.",
  ui_story_32160401_125_dialog_content = "Medalhão de coração...?",
  ui_story_32160401_126_dialog_content = "É um brinquedo de quebra-cabeça do Reino Ye, com mecanismos de travamento entrelaçados. É o dispositivo mais simples.",
  ui_story_32160401_127_dialog_content = "Mas este não é mais algo que pessoas normais podem resolver depois que eu lidei com isso.",
  ui_story_32160401_128_dialog_content = "Então eu preciso descobrir isso?",
  ui_story_32160401_129_dialog_content = "Hehe, relaxa! Só brinque um pouco com isso.",
  ui_story_32160401_130_dialog_content = "Depois de brincar com isso o suficiente, a percepção começará a surgir...",
  ui_story_32160601_1_dialog_content = "Isso deve completar meus registros!",
  ui_story_32160601_2_dialog_content = "Obrigado novamente por toda a sua ajuda hoje, PlayerName.",
  ui_story_32160601_3_dialog_content = "Eu não percebi que a Colossus poderia me dar uma visão tão clara do céu noturno. Isso é uma grande ajuda.",
  ui_story_32160601_4_dialog_content = "Não mencione isso. Tudo o que fiz foi ajustar um pouco a projeção.",
  ui_story_32160601_5_dialog_content = "Além disso, eu também gosto de ver.",
  ui_story_32160601_6_dialog_content = "Então você também gosta de olhar as estrelas?",
  ui_story_32160601_7_dialog_content = "Uhum!",
  ui_story_32160601_8_dialog_content = "Quando eu ainda estava enterrado no subsolo, Soroz me mostrava imagens do mundo exterior.",
  ui_story_32160601_9_dialog_content = "Mas quando finalmente vi as estrelas com meus próprios olhos, percebi o quão distantes elas realmente estavam...",
  ui_story_32160601_10_dialog_content = "Honestamente, isso me fez sentir um pouco triste.",
  ui_story_32160601_11_dialog_content = "Mas não tem como mudar isso, certo? Então...",
  ui_story_32160601_12_dialog_content = "Você está desenvolvendo algum tipo de nova máquina com toda essa pesquisa?",
  ui_story_32160601_13_dialog_content = "Isso mesmo! Afinal, o Festival da Primavera está logo ali na esquina.",
  ui_story_32160601_14_dialog_content = "Ahn? O que isso tem a ver com o Festival da Primavera?",
  ui_story_32160601_15_dialog_content = "Lembra que eu estudo na seita Qianyun?",
  ui_story_32160601_16_dialog_content = "Se não estivermos trabalhando em algo urgente, discípulos como eu devem visitar nosso mestre durante o Festival da Primavera.",
  ui_story_32160601_17_dialog_content = "Dessa forma, podemos ostentar - quero dizer, demonstrar os frutos do nosso trabalho naquele ano.",
  ui_story_32160601_18_dialog_content = "É por isso que sempre que o festival se aproxima, sinto uma necessidade crescente de trabalhar em algo ainda maior.",
  ui_story_32160601_19_dialog_content = "Parece interessante.",
  ui_story_32160601_20_dialog_content = "Gostaria muito de dar uma olhada na seita Qianyun algum dia.",
  ui_story_32160601_21_dialog_content = "O Reino Ye, onde a tecnologia reina suprema... Deve ser um lugar realmente especial!",
  ui_story_32160601_22_dialog_content = "Espere, falando do Festival da Primavera... Você não vai voltar este ano, vai? Isso realmente está bem?",
  ui_story_32160601_23_dialog_content = "Não posso fazer nada a respeito!",
  ui_story_32160601_24_dialog_content = "Adoraria te levar de volta e te mostrar tudo, mas é uma viagem muito longa para chegar lá.",
  ui_story_32160601_25_dialog_content = "É uma pena.",
  ui_story_32160601_26_dialog_content = "Mas...",
  ui_story_32160601_27_dialog_content = "Mas?",
  ui_story_32160601_28_dialog_content = "Acabei de ser atingido pela inspiração!",
  ui_story_32160601_29_dialog_content = "Prometo que em breve vou contar tudo sobre as minhas ideias!",
  ui_story_32160601_30_dialog_content = "<color=#e8d9bb>Alguns dias depois</color>",
  ui_story_32160601_31_dialog_content = "(A carta de Xuan Ji me disse para vir a este lugar.)",
  ui_story_32160601_32_dialog_content = "(Mas não vejo nada por aqui.)",
  ui_story_32160601_33_dialog_content = "Clique-",
  ui_story_32160601_34_dialog_content = "Um caranguejo de fogo? O que está fazendo aqui?!",
  ui_story_32160601_35_dialog_content = "Clique, clique—",
  ui_story_32160601_36_dialog_content = "Está me dizendo para ir até lá?",
  ui_story_32160601_37_dialog_content = "Piu!",
  ui_story_32160601_38_dialog_content = "Está apontando com as asas... É por aqui, certo?",
  ui_story_32160601_39_dialog_content = "Zumbido—",
  ui_story_32160601_40_dialog_content = "Onde você está me levando?!",
  ui_story_32160601_41_dialog_content = "E-Ei, não podemos simplesmente invadir o quarto de outras pessoas—",
  ui_story_32160601_42_dialog_content = "Espere, isso é...?",
  ui_story_32160601_43_dialog_content = "Ah bom, você trouxe PlayerName!",
  ui_story_32160601_44_dialog_content = "Você poderia me dizer o que está acontecendo—",
  ui_story_32160601_45_dialog_content = "Xuan... Ji?",
  ui_story_32160601_46_dialog_content = "Qual é o problema? Não me reconhece?",
  ui_story_32160601_47_dialog_content = "Não, é só que seu estilo está um pouco diferente do habitual hoje.",
  ui_story_32160601_48_dialog_content = "Estas são as vestimentas tradicionais dos discípulos da seita Qianyun. Confortáveis e práticas, certo?",
  ui_story_32160601_49_dialog_content = "Infelizmente, como todos usam exatamente o mesmo traje, nossas roupas perdem um pouco de sua singularidade.",
  ui_story_32160601_50_dialog_content = "Acho que eles combinam muito bem com você, Xuan Ji.",
  ui_story_32160601_51_dialog_content = "Quase parece que você voltou no tempo para uma época antes de nos conhecermos.",
  ui_story_32160601_52_dialog_content = "Heheh, se é assim que você se sente, então terei que usar essa roupa um pouco mais vezes.",
  ui_story_32160601_53_dialog_content = "Espere, então isso significa que este quarto também é...",
  ui_story_32160601_54_dialog_content = "Isso mesmo! É uma réplica da minha oficina em Qianyun!",
  ui_story_32160601_55_dialog_content = "Como não pude voltar este ano, pensei que poderia trazer uma parte deles para mim!",
  ui_story_32160601_56_dialog_content = "Faz sentido, certo?",
  ui_story_32160601_57_dialog_content = "Claro que sim... Espere, não!",
  ui_story_32160601_58_dialog_content = "Isso pode parecer com a sua oficina, mas nenhum dos seus colegas discípulos está aqui!",
  ui_story_32160601_59_dialog_content = "Como você pretende mostrar a eles o seu trabalho do ano?",
  ui_story_32160601_60_dialog_content = "Ah, por mim está tudo bem.",
  ui_story_32160601_61_dialog_content = "Por que você acha tão importante eu compartilhar meu trabalho com os outros?",
  ui_story_32160601_62_dialog_content = "Bem, as máquinas podem ser realmente complicadas, então se unir a outras pessoas é uma ótima maneira de aprender... Certo?",
  ui_story_32160601_63_dialog_content = "Correto.",
  ui_story_32160601_64_dialog_content = "Em outras palavras, desde que as pessoas possam se entender, elas também podem aprender umas com as outras, independentemente de seita ou origem.",
  ui_story_32160601_65_dialog_content = "Ah, uma coisinha...",
  ui_story_32160601_66_dialog_content = "Este guarda-sol em que estou trabalhando não foi feito para eles desde o início.",
  ui_story_32160601_67_dialog_content = "Ao emprestar alguns conceitos da esfera armilar e simplificar suas estruturas, e então aplicar as informações obtidas das projeções estelares do Colossus...",
  ui_story_32160601_68_dialog_content = "Eu posso produzir os movimentos das estrelas com este guarda-sol.",
  ui_story_32160601_69_option_content = "É-É lindo!",
  ui_story_32160601_70_dialog_content = "Se eu não soubesse, pensaria que era uma obra de arte ou algo assim.",
  ui_story_32160601_71_dialog_content = "Seu elogio é muito apreciado!",
  ui_story_32160601_72_option_content = "É mais do que apenas bonito.",
  ui_story_32160601_73_dialog_content = "... Desculpe, Xuan Ji.",
  ui_story_32160601_74_dialog_content = "Hã? Por que você está se desculpando?",
  ui_story_32160601_75_dialog_content = "Realmente quero oferecer meus elogios, mas não consigo pensar nas palavras certas para dizer.",
  ui_story_32160601_76_dialog_content = "A palavra \"belo\" nem começa a descrever a sensação de mistério e exploração do céu noturno...",
  ui_story_32160601_77_dialog_content = "Isso parece uma ótima maneira de colocar isso já!",
  ui_story_32160601_78_dialog_content = "Venha aqui.",
  ui_story_32160601_79_dialog_content = "Hã?",
  ui_story_32160601_80_dialog_content = "A melhor maneira de observar as estrelas é deitado de costas, certo?",
  ui_story_32160601_81_dialog_content = "D-Não acha que isso está um pouco perto demais—",
  ui_story_32160601_82_dialog_content = "Você consegue ver as sete estrelas da Ursa Maior?",
  ui_story_32160601_83_dialog_content = "Leva um ano inteiro para a alça completar um ciclo e retornar à sua posição original. É assim que sabemos quando a primavera chegou.",
  ui_story_32160601_84_dialog_content = "Em outras palavras, o Festival da Primavera?",
  ui_story_32160601_85_dialog_content = "Isso mesmo. Um novo ciclo para um novo ano.",
  ui_story_32160601_86_dialog_content = "É por isso que as pessoas se presenteiam neste dia. É a maneira delas de agradecerem umas às outras pelo passado, enquanto olham para um futuro próspero.",
  ui_story_32160601_87_dialog_content = "Estive pensando por muito tempo sobre o que te dar.",
  ui_story_32160601_88_dialog_content = "Até aquele dia, você disse que as estrelas estavam muito mais distantes de nós do que você pensava.",
  ui_story_32160601_89_dialog_content = "... Eu realmente não quis dizer nada com isso, sabe.",
  ui_story_32160601_90_dialog_content = "Ah, eu discordo.",
  ui_story_32160601_91_dialog_content = "Nossa mitologia de criação diz que quando o caos apareceu pela primeira vez, yin e yang foram separados, e as pessoas eram tanto ignorantes quanto incivilizadas.",
  ui_story_32160601_92_dialog_content = "Mas então, um dia, um sábio começou a olhar para as estrelas em busca de orientação. Ao medir e traçar seus movimentos, o tempo e o ano foram determinados, e tudo caiu em ordem.",
  ui_story_32160601_93_dialog_content = "As estrelas nos guiam de inúmeras maneiras, mas estão para sempre além do nosso alcance.",
  ui_story_32160601_94_dialog_content = "Não importa o quanto tentamos alcançar, não importa o quão altos ficamos, nunca podemos tocá-los.",
  ui_story_32160601_95_dialog_content = "Por essa razão, o céu noturno sempre foi um tipo de sonho para todos os seres vivos.",
  ui_story_32160601_96_dialog_content = "E hoje, finalmente consegui trazer esse sonho um pouco mais perto da realidade.",
  ui_story_32160601_97_dialog_content = "PlayerName. Meu caro amigo.",
  ui_story_32160601_98_dialog_content = "Gostaria de lhe presentear com este guarda-sol, bem como o sonho que ele representa.",
  ui_story_32160601_99_dialog_content = "Seja uma terra distante, ou as sempre distantes estrelas acima...",
  ui_story_32160601_100_dialog_content = "Espero que meu presente te lembre que nada está realmente fora de alcance.",
  ui_story_32160601_101_dialog_content = "Se você precisar de mim algum dia, e eu estiver em algum lugar muito longe de você...",
  ui_story_32160601_102_dialog_content = "Mantenha este guarda-sol ao seu lado e estaremos sempre perto um do outro, não importa a distância.",
  ui_story_32160601_103_dialog_content = "... Nossa.",
  ui_story_32160601_104_dialog_content = "Eu só queria saber o que te dar em troca de algo tão precioso.",
  ui_story_32160601_105_dialog_content = "Hahaha, estou apenas feliz que você goste.",
  ui_story_32160601_106_dialog_content = "Eu talvez não saiba que tipo de invenções seus colegas discípulos costumam criar.",
  ui_story_32160601_107_dialog_content = "Mas qualquer um se orgulharia incrivelmente deste guarda-sol. É uma verdadeira obra-prima.",
  ui_story_32160601_108_dialog_content = "Concordo com você nisso.",
  ui_story_32160601_109_dialog_content = "A propósito, essas estrelas...",
  ui_story_32160601_110_dialog_content = "(As estrelas cintilavam ao alcance das mãos, e o suave som das engrenagens girando chegou aos nossos ouvidos.)",
  ui_story_32160601_111_dialog_content = "(Naquele espaço tranquilo, Xuan Ji me contou todas as histórias de Longzhou sobre as estrelas.)",
  ui_story_32160601_112_dialog_content = "(Era tão tranquilo que, antes que eu percebesse, comecei a sentir sono.)",
  ui_story_32160601_113_dialog_content = "Cansando? Vá em frente e durma, se quiser.",
  ui_story_32160601_114_dialog_content = "Não se preocupe. Não há nada a temer quando você está sob o meu guarda-sol.",
  ui_story_32160601_115_dialog_content = "Seja enfrentando uma tempestade uivante ou uma horda de espíritos malignos, sempre protegerei este pequeno canto do mundo.",
  ui_story_32160601_116_dialog_content = "Afinal, debaixo deste guarda-sol...",
  ui_story_32160601_117_dialog_content = "É a minha maior conquista nesta terra."
}
return config
